result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/intervals.py", "content": """"Genomic interval algebra (BED-style: 0-based, half-open [start, end))."""

from __future__ import annotations

Interval = tuple[int, int]


def _validate(ivs):
    for s, e in ivs:
        if not (0 <= s <= e):
            raise ValueError(f"invalid interval ({s}, {e}); require 0 <= start <= end")


def merge(intervals) -> list[Interval]:
    """Merge overlapping or adjacent intervals; result is sorted and disjoint."""
    ivs = sorted((int(s), int(e)) for s, e in intervals)
    out: list[Interval] = []
    for s, e in ivs:
        if out and s <= out[-1][1]:  # overlap or adjacency
            if e > out[-1][1]:
                out[-1] = (out[-1][0], e)
        else:
            out.append((s, e))
    return out


def intersect(a, b) -> list[Interval]:
    """Intersect two interval sets."""
    a = merge(a)
    b = merge(b)
    out: list[Interval] = []
    i = j = 0
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            out.append((s, e))
        if a[i][1] <= b[j][1]:
            i += 1
        else:
            j += 1
    return out


def subtract(a, b) -> list[Interval]:
    """Intervals in a with everything in b removed."""
    a = merge(a)
    b = merge(b)
    out: list[Interval] = []
    j = 0
    for s, e in a:
        cur = s
        # skip blockers entirely before cur
        while j < len(b) and b[j][1] <= cur:
            j += 1
        k = j
        while k < len(b) and b[k][0] < e:
            bs, be = b[k]
            if bs > cur:
                out.append((cur, bs))
            cur = max(cur, be)
            k += 1
        if cur < e:
            out.append((cur, e))
    return out


def complement(intervals, chrom_length: int) -> list[Interval]:
    """Gaps within [0, chrom_length) not covered by any interval."""
    if chrom_length < 0:
        raise ValueError("chrom_length must be non-negative")
    covered = merge(intervals)
    out: list[Interval] = []
    cur = 0
    for s, e in covered:
        if s > cur:
            out.append((cur, s))
        cur = max(cur, e)
    if cur < chrom_length:
        out.append((cur, chrom_length))
    return out
