import pytest

from intervals import complement, intersect, merge, subtract


# --- exact answers -------------------------------------------------------

def test_merge_exact():
    assert merge([(1, 5), (4, 8), (10, 12)]) == [(1, 8), (10, 12)]


def test_intersect_exact():
    assert intersect([(1, 10)], [(5, 15)]) == [(5, 10)]


def test_subtract_exact():
    assert subtract([(0, 10)], [(3, 5)]) == [(0, 3), (5, 10)]


def test_complement_exact():
    assert complement([(2, 4), (6, 8)], 10) == [(0, 2), (4, 6), (8, 10)]


# --- brute-force reference ----------------------------------------------

MAX_LEN = 40


def bitmap_union(intervals, length=MAX_LEN):
    bm = bytearray(length)
    for s, e in intervals:
        assert 0 <= s <= e <= length
        for p in range(s, e):
            bm[p] = 1
    return bm


def bitmap_to_intervals(bm):
    out = []
    i = 0
    n = len(bm)
    while i < n:
        if bm[i]:
            j = i
            while j < n and bm[j]:
                j += 1
            out.append((i, j))
            i = j
        else:
            i += 1
    return out


def brute_merge(ivs):
    return bitmap_to_intervals(bitmap_union(ivs))


def brute_intersect(a, b):
    return bitmap_to_intervals(bytes(x & y for x, y in zip(bitmap_union(a), bitmap_union(b))))


def brute_subtract(a, b):
    ba, bb = bitmap_union(a), bitmap_union(b)
    return bitmap_to_intervals(bytes(x & (1 - y) for x, y in zip(ba, bb)))


def brute_complement(ivs, length=MAX_LEN):
    bm = bitmap_union(ivs, length)
    return bitmap_to_intervals(bytes(1 - x for x in bm))


def random_interval_set(rng, max_n=6):
    ivs = []
    for _ in range(rng.randint(0, max_n)):
        s = rng.randint(0, MAX_LEN - 1)
        e = rng.randint(s, MAX_LEN)
        ivs.append((s, e))
    return ivs


# --- property tests (seed 17) -------------------------------------------

@pytest.fixture
def rng():
    return random.Random(17)


def test_merge_idempotent_and_order_insensitive(rng):
    for _ in range(500):
        ivs = random_interval_set(rng)
        m1 = merge(ivs)
        assert m1 == merge(m1)                      # idempotent
        shuffled = ivs[:]
        random.Random(rng.random()).shuffle(shuffled)
        assert merge(shuffled) == m1                # order-insensitive
        assert m1 == brute_merge(ivs)               # matches brute force


def test_intersect_matches_brute(rng):
    for _ in range(500):
        a, b = random_interval_set(rng), random_interval_set(rng)
        assert intersect(a, b) == brute_intersect(a, b)


def test_subtract_matches_brute(rng):
    for _ in range(500):
        a, b = random_interval_set(rng), random_interval_set(rng)
        assert subtract(a, b) == brute_subtract(a, b)


def test_complement_matches_brute(rng):
    for _ in range(500):
        ivs = random_interval_set(rng)
        length = rng.randint(0, MAX_LEN)
        assert complement(ivs, length) == brute_complement(ivs, length)


def test_algebraic_invariant(rng):
    # A minus B, unioned back with the intersection of A and B, recovers A.
    for _ in range(300):
        a, b = random_interval_set(rng), random_interval_set(rng)
        assert merge(subtract(a, b) + intersect(a, b)) == merge(a)
